package cli

import (
	"os/exec"
	"runtime/debug"
	"strings"
	"testing"
)

// TestGSXVersionMatchesGoMod guards the pin `gsxui init` hands a project: it
// is the gsx version gsxui's own go.mod selects, the one its components are
// generated by and tested against.
func TestGSXVersionMatchesGoMod(t *testing.T) {
	got, err := gsxVersion()
	if err != nil {
		t.Fatal(err)
	}
	if want := selectedModuleVersion(t, ".", gsxModule); got != want {
		t.Fatalf("gsxVersion() = %q, want go.mod's %q", got, want)
	}
}

func TestModuleVersion(t *testing.T) {
	const path = "example.com/lib"
	tests := []struct {
		name    string
		deps    []*debug.Module
		want    string
		wantErr string
	}{
		{
			name: "selected version",
			deps: []*debug.Module{{Path: "example.com/other", Version: "v9.0.0"}, {Path: path, Version: "v1.2.3"}},
			want: "v1.2.3",
		},
		{
			name: "replaced module keeps its required version",
			deps: []*debug.Module{{Path: path, Version: "v1.2.3", Replace: &debug.Module{Path: "../lib", Version: ""}}},
			want: "v1.2.3",
		},
		{
			name:    "absent",
			deps:    []*debug.Module{{Path: "example.com/other", Version: "v1.0.0"}},
			wantErr: "does not list it",
		},
		{
			name:    "devel",
			deps:    []*debug.Module{{Path: path, Version: "(devel)"}},
			wantErr: "records no version",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := moduleVersion(&debug.BuildInfo{Deps: tt.deps}, path)
			if tt.wantErr != "" {
				if err == nil || !strings.Contains(err.Error(), tt.wantErr) {
					t.Fatalf("moduleVersion() = %q, %v; want error containing %q", got, err, tt.wantErr)
				}
				return
			}
			if err != nil || got != tt.want {
				t.Fatalf("moduleVersion() = %q, %v; want %q", got, err, tt.want)
			}
		})
	}
}

// selectedModuleVersion is the version of module that the build list of the
// module containing dir selects.
func selectedModuleVersion(t *testing.T, dir, module string) string {
	t.Helper()
	cmd := exec.Command("go", "list", "-m", "-f", "{{.Version}}", module)
	cmd.Dir = dir
	output, err := cmd.Output()
	if err != nil {
		t.Fatalf("go list -m %s in %s: %v", module, dir, err)
	}
	version := strings.TrimSpace(string(output))
	if version == "" {
		t.Fatalf("go list -m %s in %s: empty version", module, dir)
	}
	return version
}
